/* Automated test driver for Lab 10. DO NOT EDIT THIS FILE. */
public class Lab10MatrixOpsTest {

    public static void main(String[] args) {

        int[][] a = {{1, 2, 3}, {4, 5, 6}};              // 2 x 3
        int[][] b = {{7, 8}, {9, 10}, {11, 12}};          // 3 x 2
        int[][] square = {{2, 7}, {7, 3}};                // symmetric
        int[][] notSymmetric = {{2, 7}, {1, 3}};
        int[][] identity = {{1, 0}, {0, 1}};

        TestRunner.section("rowSums");
        TestRunner.checkArray("rows of the 2x3 matrix", new int[]{6, 15}, Lab10MatrixOps.rowSums(a));
        TestRunner.checkArray("rows of the 3x2 matrix", new int[]{15, 19, 23}, Lab10MatrixOps.rowSums(b));
        TestRunner.checkArray("rows of the identity", new int[]{1, 1}, Lab10MatrixOps.rowSums(identity));

        TestRunner.section("columnSums");
        TestRunner.checkArray("columns of the 2x3 matrix", new int[]{5, 7, 9}, Lab10MatrixOps.columnSums(a));
        TestRunner.checkArray("columns of the 3x2 matrix", new int[]{27, 30}, Lab10MatrixOps.columnSums(b));

        TestRunner.section("transpose");
        TestRunner.checkArray2D("2x3 transposes to 3x2",
                new int[][]{{1, 4}, {2, 5}, {3, 6}}, Lab10MatrixOps.transpose(a));
        TestRunner.checkArray2D("transposing twice restores the original",
                a, Lab10MatrixOps.transpose(Lab10MatrixOps.transpose(a)));
        TestRunner.checkArray2D("the identity is its own transpose",
                identity, Lab10MatrixOps.transpose(identity));

        TestRunner.section("multiply");
        TestRunner.checkArray2D("(2x3) * (3x2) = (2x2)",
                new int[][]{{58, 64}, {139, 154}}, Lab10MatrixOps.multiply(a, b));
        TestRunner.checkArray2D("(3x2) * (2x3) = (3x3)",
                new int[][]{{39, 54, 69}, {49, 68, 87}, {59, 82, 105}}, Lab10MatrixOps.multiply(b, a));
        TestRunner.checkArray2D("multiplying by the identity changes nothing",
                square, Lab10MatrixOps.multiply(square, identity));
        TestRunner.checkTrue("non-conforming shapes return null",
                Lab10MatrixOps.multiply(a, a) == null);

        TestRunner.section("isSymmetric");
        TestRunner.checkTrue("{{2,7},{7,3}} is symmetric", Lab10MatrixOps.isSymmetric(square));
        TestRunner.checkTrue("the identity is symmetric", Lab10MatrixOps.isSymmetric(identity));
        TestRunner.checkFalse("{{2,7},{1,3}} is not symmetric", Lab10MatrixOps.isSymmetric(notSymmetric));
        TestRunner.checkFalse("a non-square matrix is not symmetric", Lab10MatrixOps.isSymmetric(a));

        TestRunner.section("largest");
        TestRunner.check("largest in the 2x3 matrix", 6, Lab10MatrixOps.largest(a));
        TestRunner.check("largest in the 3x2 matrix", 12, Lab10MatrixOps.largest(b));
        TestRunner.check("largest with negatives", -1, Lab10MatrixOps.largest(new int[][]{{-9, -4}, {-1, -7}}));

        TestRunner.exitWithSummary();
    }
}
